287	        boolean balanced = total.compareTo(FULL) == 0;
288	        boolean[] noCut = new boolean[members.size()];
289	        boolean allRetired = true;
290	        for (int i = 0; i < members.size(); i++) {
291	            PoolMember m = members.get(i);
292	            noCut[i] = outside[i] || retired[i] || (!m.isPool() && held.contains(m.personId()));
293	            if (!outside[i] && !retired[i]) {
294	                allRetired = false;
295	            }
296	        }
297	        BigDecimal[] cuts = balanced && pot != null && !allRetired ? cuts(members, noCut, pot) : null;
298	        List<Member> shown = new ArrayList<>();
299	        for (int i = 0; i < members.size(); i++) {
300	            PoolMember m = members.get(i);
301	            shown.add(new Member(m.isPool() ? null : m.personId(), m.name(), m.share().toPlainString(), retired[i],
302	                    cuts != null && !outside[i] ? cuts[i].toPlainString() : "", m.memberPoolId(), date(m.from()),
303	                    date(m.to()), outside[i]));
