316	    private static BigDecimal[] cuts(List<PoolMember> members, boolean[] noCut, BigDecimal pot) {
317	        BigDecimal[] cuts = new BigDecimal[members.size()];
318	        BigDecimal shares = BigDecimal.ZERO;
319	        for (int i = 0; i < members.size(); i++) {
320	            if (!noCut[i]) {
321	                shares = shares.add(members.get(i).share());
322	            }
323	        }
324	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
325	        int smallest = -1;
326	        int last = -1;
327	        for (int i = 0; i < members.size(); i++) {
328	            BigDecimal share = members.get(i).share();
329	            cuts[i] = noCut[i] ? BigDecimal.ZERO.setScale(2)
330	                    : pot.multiply(share).divide(shares, 2, RoundingMode.HALF_EVEN);
331	            sum = sum.add(cuts[i]);
332	            if (noCut[i]) {
333	                continue;
334	            }
335	            if (share.signum() != 0) {
336	                last = i;
337	            }
338	            if (cuts[i].signum() != 0 && (smallest < 0 || cuts[i].compareTo(cuts[smallest]) <= 0)) {
339	                smallest = i;
340	            }
341	        }
342	        int to = smallest >= 0 ? smallest : last;
343	        if (to >= 0) {
344	            cuts[to] = cuts[to].add(pot.subtract(sum));
345	        }
346	        return cuts;
347	    }
