393	/** The sheet's pools in the order they were added, with their members, total share and whether balanced; a member
394	 *  retired by the sheet's today (or the as-of date, when one is given) cuts 0.00, their share still counted toward the total
395	 *  and spread over the members with a cut (no cuts at all when every member is retired); each member of a balanced pool
396	 *  shows their cut of the pool's pot (when there is one). A pool that is a member of none has the sheet's pot (as it stood
397	 *  then, given an as-of date); a pool
398	 *  that is a member of another has its cut there as its pot (none when the pool above has no cuts). A person with a
399	 *  hold in force on that date cuts 0.00, their share spread over the members with a cut. A member whose membership
400	 *  dates do not include that date is left out: no share in the total and no cut. */
401	public class RespondWithPools {
402	    public void respond(@PathVariable("sheetId") String sheetId,
403	            @RequestParam(name = "asOf", required = false) String asOf, PoolRepository repository,
404	            PersonRepository people, SheetRepository sheets, SettingRepository settings,
405	            ObjectResponse<List<PoolResponse>> response) {
406	        String id = sheetId.trim();
407	        LocalDate end = AsOf.parse(asOf);
408	        LocalDate on = end != null ? end : sheets.today(id);
409	        List<Person> persons = end != null ? people.listAsOf(id, end) : people.list(id);
410	        Map<Long, LocalDate> retiredFrom = new HashMap<>();
411	        Map<Long, String> names = new HashMap<>();
412	        Set<Long> held = new HashSet<>();
413	        BigDecimal pot = end != null ? settings.potAsOf(id, end) : settings.pot(id);
414	        for (Person p : persons) {
415	            names.put(p.id(), p.name());
416	            if (p.retiredFrom() != null) {
417	                retiredFrom.put(p.id(), p.retiredFrom());
418	            }
419	            if (on != null && p.holds().covers(on)) {
420	                held.add(p.id());
421	            }
422	        }
423	        List<Pool> pools = repository.list(id, end);
424	        Map<Long, String> poolNames = new HashMap<>();
425	        pools.forEach(p -> poolNames.put(p.id(), p.name()));
426	        Map<Long, List<PoolMember>> members = new HashMap<>();
427	        Map<Long, Pool> parents = new HashMap<>();
428	        for (Pool pool : pools) {
429	            List<PoolMember> named = repository.members(pool, end).stream()
430	                    .filter(m -> m.isPool() ? poolNames.containsKey(m.memberPoolId())
431	                            : names.containsKey(m.personId()))
432	                    .map(m -> m.named(m.isPool() ? poolNames.get(m.memberPoolId()) : names.get(m.personId())))
433	                    .toList();
434	            members.put(pool.id(), named);
435	            named.stream().filter(PoolMember::isPool).forEach(m -> parents.put(m.memberPoolId(), pool));
436	        }
437	        Map<Long, PoolResponse> shown = new HashMap<>();
438	        response.send(pools.stream()
439	                .map(pool -> shown(pool, members, parents, retiredFrom, held, on, pot, shown)).toList());
440	    }
441	
442	    /** The pool as shown, its pot the sheet's or its cut in the pool above (worked out first). */
443	    private static PoolResponse shown(Pool pool, Map<Long, List<PoolMember>> members, Map<Long, Pool> parents,
444	            Map<Long, LocalDate> retiredFrom, Set<Long> held, LocalDate on, BigDecimal sheetPot, Map<Long, PoolResponse> shown) {
445	        PoolResponse done = shown.get(pool.id());
446	        if (done != null) {
447	            return done;
448	        }
449	        Pool above = parents.get(pool.id());
450	        BigDecimal pot = above == null ? sheetPot
451	                : shown(above, members, parents, retiredFrom, held, on, sheetPot, shown).cutOf(pool.id());
452	        PoolResponse r = PoolResponse.from(pool, members.get(pool.id()), retiredFrom, held, on, pot);
453	        shown.put(pool.id(), r);
454	        return r;
455	    }
