487	/** Store the member, refusing an unknown pool or person, or a person already in the pool. A member pool is refused
488	 *  when it is already a member of a pool, when it is the pool itself or contains it through any chain, or when the
489	 *  chain of pools would be more than three deep. */
490	public class SavePoolMember {
491	    public void save(@PathVariable("sheetId") String sheetId, @PathVariable("poolId") String poolId,
492	            @Val PoolMemberInput input, PeriodRepository periods, PoolRepository repository, PersonRepository people,
493	            Out<PoolMember> member) throws InvalidPoolException {
494	        String id = sheetId.trim();
495	        periods.lockSheet(id);
496	        Pool pool;
497	        try {
498	            pool = repository.find(id, Long.parseLong(poolId.trim()));
499	        } catch (NumberFormatException e) {
500	            pool = null;
501	        }
502	        if (pool == null) {
503	            throw new InvalidPoolException("No pool " + poolId + " on this sheet.");
504	        }
505	        if (input.memberPoolId() != null) {
506	            member.set(repository.addMember(pool, memberPool(id, pool, input.memberPoolId(), repository), input));
507	            return;
508	        }
509	        Person person = people.find(id, input.personId());
510	        if (person == null) {
511	            throw new InvalidPoolException("No person " + input.personId() + " on this sheet.");
512	        }
513	        if (repository.isMember(pool, person.id())) {
514	            throw new InvalidPoolException(person.name() + " is already in " + pool.name() + ".");
515	        }
516	        member.set(repository.addMember(pool, person, input));
517	    }
518	
519	    private static final int MAX_DEPTH = 3;
520	
521	    private static Pool memberPool(String sheetId, Pool pool, long memberPoolId, PoolRepository repository)
522	            throws InvalidPoolException {
523	        Pool child = repository.find(sheetId, memberPoolId);
524	        if (child == null) {
525	            throw new InvalidPoolException("No pool " + memberPoolId + " on this sheet.");
526	        }
527	        if (child.id() == pool.id()) {
528	            throw new InvalidPoolException("A pool cannot be a member of itself.");
529	        }
530	        Pool above = repository.parent(child);
531	        if (above != null) {
532	            throw new InvalidPoolException(child.name() + " is already a member of " + above.name() + ".");
533	        }
534	        int depth = 1;
535	        for (Pool p = repository.parent(pool); p != null; p = repository.parent(p)) {
536	            if (p.id() == child.id()) {
537	                throw new InvalidPoolException(pool.name() + " is already within " + child.name() + ".");
538	            }
539	            depth++;
540	        }
541	        if (depth + height(child, repository) > MAX_DEPTH) {
542	            throw new InvalidPoolException("A chain of pools is at most " + MAX_DEPTH + " deep.");
543	        }
544	        return child;
545	    }
546	
547	    /** How many levels of pools this pool heads, itself included. */
548	    private static int height(Pool pool, PoolRepository repository) {
549	        int below = 0;
550	        for (Pool c : repository.children(pool)) {
551	            below = Math.max(below, height(c, repository));
552	        }
553	        return below + 1;
554	    }
555	}
